bool Read_GetGroundDecalTexturesResult(const WasmValue& input, GetGroundDecalTexturesResult& output, NativeCallStorage& storage, std::string& error)
{
	const auto* record = std::get_if<WasmValueRecord>(&input.storage);
	if (record == nullptr) { error = "Wasm argument is not a record"; return false; }
	const auto* value_textures = FindRecordField(*record, "textures", error);
	if (value_textures == nullptr) return false;
	const auto* list_textures = std::get_if<WasmValueList>(&(*value_textures).storage);
	if (list_textures == nullptr) { error = "Wasm argument is not a list"; return false; }
	auto& native_textures = storage.Make<std::vector<std::string>>();
	native_textures.reserve(list_textures->size());
	for (const auto& item : *list_textures) {
		std::string item_value{};
		auto& stored_string_item_value = storage.Make<std::string>();
		if (!ReadString(item, stored_string_item_value, error)) { return false; }
		item_value = stored_string_item_value.c_str();
		native_textures.push_back(std::move(item_value));
	}
	auto& pointers_textures = storage.Make<std::vector<const char*>>();
	pointers_textures.reserve(native_textures.size());
	for (const auto& item : native_textures) pointers_textures.push_back(item.c_str());
	output.textures = pointers_textures.data();
	if (!AssignCount(list_textures->size(), output.textureCount, error)) { return false; }
	const auto* value_filenames = FindRecordField(*record, "filenames", error);
	if (value_filenames == nullptr) return false;
	const auto* list_filenames = std::get_if<WasmValueList>(&(*value_filenames).storage);
	if (list_filenames == nullptr) { error = "Wasm argument is not a list"; return false; }
	auto& native_filenames = storage.Make<std::vector<std::string>>();
	native_filenames.reserve(list_filenames->size());
	for (const auto& item : *list_filenames) {
		std::string item_value{};
		auto& stored_string_item_value = storage.Make<std::string>();
		if (!ReadString(item, stored_string_item_value, error)) { return false; }
		item_value = stored_string_item_value.c_str();
		native_filenames.push_back(std::move(item_value));
	}
	auto& pointers_filenames = storage.Make<std::vector<const char*>>();
	pointers_filenames.reserve(native_filenames.size());
	for (const auto& item : native_filenames) pointers_filenames.push_back(item.c_str());
	output.filenames = pointers_filenames.data();
	if (!AssignCount(list_filenames->size(), output.filenameCount, error)) { return false; }
	return true;
}

WasmValue Write_GetGroundDecalTexturesResult(const GetGroundDecalTexturesResult& value)
{
	WasmValueRecord fields;
	fields.emplace("textures", WriteNativeList(value.textures, value.textureCount, [](const auto& value) { return WasmValue::String(value == nullptr ? std::string{} : std::string(value)); }));
	fields.emplace("filenames", WriteNativeList(value.filenames, value.filenameCount, [](const auto& value) { return WasmValue::String(value == nullptr ? std::string{} : std::string(value)); }));
	return WasmValue::Record(std::move(fields));
}

